INSERT OR IGNORE INTO questions (id,question_text,slug,publication_state,visibility,claimed_status,verification_state,category_id,category_name,context_summary,public_json,submission_state,publisher_motivation) VALUES ('pilot-2026-01','Why do some biological systems recover from disturbance while others reorganize permanently?','why-do-some-biological-systems-recover-from-disturbance-while-others-reorganize-permanently','DRAFT','PRIVATE','PARTIALLY_ANSWERED','PENDING','science','Science','Recovery can mean returning to an earlier state, retaining a function, or forming a viable new organization, and those outcomes can diverge after the same disturbance. Tambaya follows how this question changed, what evidence makes it difficult, and why its framing matters without presenting an answer.','{}','SUBMITTED','Editorial pilot: independently formulated question for review before public release.');
