INSERT OR IGNORE INTO questions (id,question_text,slug,publication_state,visibility,claimed_status,verification_state,category_id,category_name,context_summary,public_json,submission_state,publisher_motivation) VALUES ('pilot-2026-20','How should medicine study recovery when patients define it differently?','how-should-medicine-study-recovery-when-patients-define-it-differently','DRAFT','PRIVATE','OPEN','PENDING','health-medicine','Health & Medicine','Recovery may mean symptom relief, restored function, independence, identity, participation, adaptation, or freedom from treatment, and these aims can conflict within the same case. Tambaya follows how this question changed, what evidence makes it difficult, and why its framing matters without presenting an answer.','{}','SUBMITTED','Editorial pilot: independently formulated question for review before public release.');
